#!/usr/bin/env bash
set -euo pipefail
ROOT_DIR="$(pwd)"
BUILD_DIR="${ROOT_DIR}/build"
SRC_DIR="${ROOT_DIR}/jaide_v26_ultimate/runtime"
HARDWARE_DIR="${ROOT_DIR}/jaide_v26_ultimate/hardware"
GPU_DIR="${ROOT_DIR}/jaide_v26_ultimate/gpu"
LIB_NAME="libjaide_v26.so"

if ! command -v zig &> /dev/null; then
  echo "Zig compiler could not be found. Please install Zig (>=0.12.0) and ensure it's in your PATH."
  exit 1
fi
if ! command -v futhark &> /dev/null; then
  echo "Futhark compiler could not be found. Please install Futhark and ensure it's in your PATH."
  exit 1
fi

echo "--- JAIDE V26 Ultimate Build Environment ---"
echo "Root Directory: ${ROOT_DIR}"
echo "Build Directory: ${BUILD_DIR}"
echo "Zig Version: $(zig version)"
echo "Futhark Version: $(futhark --version)"
echo "-----------------------------------"

echo "[1/4] Cleaning and preparing build directory..."
rm -rf "${BUILD_DIR}"
mkdir -p "${BUILD_DIR}"
echo "Build directory prepared at ${BUILD_DIR}"

echo "[2/4] 'Synthesizing' Verilog hardware modules (simulation)..."
cp -r "${HARDWARE_DIR}" "${BUILD_DIR}/hardware"
echo "Hardware modules copied to build directory."

echo "[3/4] Compiling Futhark GPU kernels to C library..."
futhark c --library -o "${BUILD_DIR}/futhark_kernels" "${GPU_DIR}/kernels/"*.fut
echo "Futhark kernels compiled successfully."

echo "[4/4] Compiling Zig native runtime into a shared library..."
zig build-lib \
  -O ReleaseFast \
  -fPIC \
  -dynamic \
  --name jaide_v26 \
  -I"${BUILD_DIR}" \
  -L"${BUILD_DIR}" \
  -lc \
  -lfuthark_kernels \
  "${SRC_DIR}/core/main.zig"
mv "libjaide_v26.so" "${BUILD_DIR}/${LIB_NAME}"

echo "-----------------------------------"
echo "JAIDE V26 ULTIMATE NATIVE BUILD COMPLETE"
echo "Library available at: ${BUILD_DIR}/${LIB_NAME}"
echo "-----------------------------------"
exit 0

