class NotFoundError(FileNotFoundError):
    pass


class SystemConfig:
    def __init__(self, config_path: Path):
        if not config_path.exists():
            raise NotFoundError(f"Configuration not found at {config_path}")
        try:
            with open(config_path, 'r', encoding='utf-8') as f:
                self.config_data = json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON in configuration: {e}") from e

    def get(self, section: str, key: str, default: Any = None) -> Any:
        return self.config_data.get(section, {}).get(key, default)

    def get_native_config_json(self) -> str:
        return json.dumps(self.config_data.get("native_config", {}))


class V26NativeBridge:
    def __init__(self, lib_path: Path, config_json: str):
        if not lib_path.exists():
            raise NotFoundError(f"JAIDE V26 native library not found at {lib_path}")
        self.lib = ctypes.CDLL(str(lib_path))
        self._define_api()
        config_bytes = config_json.encode('utf-8')
        self.system_handle = self.lib.jaide_v26_system_create(ctypes.c_char_p(config_bytes))
        if not self.system_handle:
            raise RuntimeError("Failed to create JAIDE V26 system handle.")

    def _define_api(self):
        self.lib.jaide_v26_system_create.argtypes = [ctypes.c_char_p]
        self.lib.jaide_v26_system_create.restype = ctypes.c_void_p

        self.lib.jaide_v26_system_destroy.argtypes = [ctypes.c_void_p]
        self.lib.jaide_v26_system_destroy.restype = None

        self.lib.jaide_v26_run_inference.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.POINTER(ctypes.c_char_p)]
        self.lib.jaide_v26_run_inference.restype = ctypes.c_int

        self.lib.jaide_v26_run_distributed_training.argtypes = [ctypes.c_void_p, ctypes.c_char_p]
        self.lib.jaide_v26_run_distributed_training.restype = ctypes.c_bool

        self.lib.jaide_v26_run_quantum_analysis.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_char_p, ctypes.POINTER(ctypes.c_double)]
        self.lib.jaide_v26_run_quantum_analysis.restype = ctypes.c_int

        self.lib.jaide_v26_free_string.argtypes = [ctypes.c_void_p, ctypes.c_char_p]
        self.lib.jaide_v26_free_string.restype = None

    def run_inference(self, prompt: str) -> str:
        prompt_bytes = prompt.encode('utf-8')
        response_ptr = ctypes.c_char_p()
        result_code = self.lib.jaide_v26_run_inference(self.system_handle, prompt_bytes, ctypes.byref(response_ptr))
        if result_code != 0:
            raise RuntimeError(f"Native inference failed with error code {result_code}")
        response_str = ctypes.cast(response_ptr, ctypes.c_char_p).value.decode('utf-8')
        self.lib.jaide_v26_free_string(self.system_handle, response_ptr)
        return response_str

    def destroy(self):
        if getattr(self, 'system_handle', None):
            self.lib.jaide_v26_system_destroy(self.system_handle)
            self.system_handle = None


class EnhancedHGM:
    def __init__(self, params_generator: Generator, config: Dict[str, Any]):
        self.param_groups = list(params_generator)
        self.state = {id(p): {} for group in self.param_groups for p in group['params']}
        self.defaults = config
        self.lr_base = self.defaults['lr']

    def zero_grad(self):
        for group in self.param_groups:
            for p in group['params']:
                if hasattr(p, 'grad') and p.grad is not None:
                    p.grad.fill(0)

    def step(self):
        global_cos_sim_avg = 0.0
        num_params = 0
        for group in self.param_groups:
            k = group.get('heuristic_momentum_window', self.defaults['heuristic_momentum_window'])
            for p in group['params']:
                if not hasattr(p, 'grad') or p.grad is None:
                    continue
                state = self.state.get(id(p))
                if not state or 'step' not in state:
                    continue
                if state['step'] > k:
                    history, grad = state['grad_history'], p.grad
                    avg_past_grad = np.mean(history, axis=0)
                    norm_grad, norm_avg_past = np.linalg.norm(grad), np.linalg.norm(avg_past_grad)
                    if norm_grad > self.defaults['eps'] and norm_avg_past > self.defaults['eps']:
                        cos_sim = float(np.dot(grad.flatten(), avg_past_grad.flatten()) / (norm_grad * norm_avg_past))
                        global_cos_sim_avg += cos_sim
                        num_params += 1
        current_lr = self.lr_base * ((1.0 + max(-0.5, min(1.0, global_cos_sim_avg / num_params))) / 2.0) if num_params > 0 else self.lr_base
        for group in self.param_groups:
            group['lr'] = current_lr
            k = group.get('heuristic_momentum_window', self.defaults['heuristic_momentum_window'])
            beta1, beta2 = group.get('betas', self.defaults['betas'])
            eps = group.get('eps', self.defaults['eps'])
            wd = group.get('weight_decay', self.defaults['weight_decay'])
            for p in group['params']:
                if not hasattr(p, 'grad') or p.grad is None:
                    continue
                grad = p.grad
                if np.any(np.isinf(grad)) or np.any(np.isnan(grad)):
                    continue
                state = self.state[id(p)]
                if 'step' not in state:
                    state.update({
                        'step': 0,
                        'exp_avg': np.zeros_like(p.data),
                        'exp_avg_sq': np.zeros_like(p.data),
                        'grad_history': np.zeros((k,) + p.data.shape, dtype=p.data.dtype),
                        'fisher_diag': np.zeros_like(p.data)
                    })
                state['step'] += 1
                if wd > 0:
                    p.data *= (1.0 - current_lr * wd)
                history = state['grad_history']
                history[state['step'] % k] = grad
                dynamic_beta1 = beta1
                if state['step'] > k:
                    avg_past_grad = np.mean(history, axis=0)
                    norm_grad, norm_avg_past = np.linalg.norm(grad), np.linalg.norm(avg_past_grad)
                    if norm_grad > eps and norm_avg_past > eps:
                        cos_sim = float(np.dot(grad.flatten(), avg_past_grad.flatten()) / (norm_grad * norm_avg_past))
                        dynamic_beta1 = min(beta1 + (1.0 - beta1) * max(0.0, cos_sim) ** 2, 0.9999)
                exp_avg, exp_avg_sq = state['exp_avg'], state['exp_avg_sq']
                state['exp_avg'] = (dynamic_beta1 * exp_avg + (1 - dynamic_beta1) * grad)
                state['exp_avg_sq'] = (beta2 * exp_avg_sq + (1 - beta2) * (grad ** 2))
                if self.defaults['fisher_approximation']:
                    state['fisher_diag'] = 0.99 * state['fisher_diag'] + 0.01 * (grad ** 2)
                bias_correction1 = 1.0 - dynamic_beta1 ** state['step']
                bias_correction2 = 1.0 - beta2 ** state['step']
                step_size = current_lr / bias_correction1
                preconditioner = np.sqrt(state['exp_avg_sq'] / bias_correction2)
                if self.defaults['structured_updates']:
                    preconditioner = preconditioner + np.sqrt(state['fisher_diag'])
                update = step_size * (state['exp_avg'] / (preconditioner + eps))
                if group.get('is_state_matrix', False) and p.data.ndim == 2:
                    row_sums = np.sum(np.abs(p.data), axis=1)
                    target = group.get('state_matrix_spectral_radius_target', self.defaults['state_matrix_spectral_radius_target'])
                    strength = group.get('state_matrix_regularization_strength', self.defaults['state_matrix_regularization_strength'])
                    overshoot = np.maximum(0, row_sums - target)
                    update = update + current_lr * strength * (np.sign(p.data) * overshoot[:, np.newaxis])
                p.data -= update


