const std = @import("std");
const SML = @import("../memory/spectral_lattice.zig");
const HSM = @import("../state/holographic_sm.zig");
const HCE = @import("../../tokenizer/holographic_encoder.zig");
const TGN = @import("../model/temporal_graph_net.zig");
const Futhark = @import("../gpu/futhark_bridge.zig");

var sml_instance: ?SML.SpectralMemoryLattice = null;
var g_allocator: std.mem.Allocator = undefined;

pub const JaideSystem = struct {
    allocator: std.mem.Allocator,
    state_machine: HSM.HolographicStateMachine,
    encoder: HCE.HolographicEncoder,
    graph: TGN.TemporalGraph,
    futhark_context: *Futhark.Context,
};

export fn jaide_v26_system_create(config_json_ptr: [*c]const u8) ?*JaideSystem {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    const backing_allocator = gpa.allocator();

    sml_instance = SML.SpectralMemoryLattice.init(backing_allocator, 1024 * 1024 * 1024 * 8) catch return null;
    g_allocator = sml_instance.?.allocator();

    var system = g_allocator.create(JaideSystem) catch return null;
    system.* = .{
        .allocator = g_allocator,
        .state_machine = HSM.HolographicStateMachine.init(g_allocator),
        .encoder = HCE.HolographicEncoder.init(g_allocator),
        .graph = TGN.TemporalGraph.init(g_allocator),
        .futhark_context = Futhark.Context.init(g_allocator) catch return null,
    };

    _ = config_json_ptr;

    system.state_machine.beginInitialization() catch return null;
    system.state_machine.completeInitialization() catch return null;
    return system;
}

export fn jaide_v26_system_destroy(system: *JaideSystem) void {
    system.state_machine.state = .Shutdown;
    system.futhark_context.deinit();
    system.graph.deinit();
    system.encoder.deinit();
    system.state_machine.deinit();
    g_allocator.destroy(system);
    if (sml_instance) |*sml| sml.deinit();
}

export fn jaide_v26_run_inference(system: *JaideSystem, prompt_ptr: [*c]const u8, out_response: *[*c]u8) c_int {
    system.state_machine.startInference(1) catch return -1;
    defer system.state_machine.completeInference() catch {};

    const prompt = std.mem.span(prompt_ptr);
    var toks = std.ArrayList([]const u8).init(system.allocator);
    defer toks.deinit();

    var it = std.mem.tokenizeAny(u8, prompt, " \t\r\n");
    while (it.next()) |tok| {
        toks.append(tok) catch return -3;
    }
    if (toks.items.len == 0) {
        const empty = "Empty prompt";
        const cstr = system.allocator.dupeZ(u8, empty) catch return -4;
        out_response.* = cstr;
        return 0;
    }

    const _hvec = system.encoder.encodeSequence(toks.items) catch return -2;
    const msg = std.fmt.allocPrint(system.allocator, "Response from JAIDE V26 Ultimate | tokens={} dim={}", .{ toks.items.len, HCE.HDS_DIM }) catch return -4;
    out_response.* = msg;
    return 0;
}

export fn jaide_v26_free_string(system: *JaideSystem, str_ptr: [*c]u8) void {
    system.allocator.free(std.mem.span(str_ptr));
}

export fn jaide_v26_run_distributed_training(system: *JaideSystem, dataset_path_ptr: [*c]const u8) bool {
    system.state_machine.startTraining() catch return false;
    defer system.state_machine.completeTraining() catch {};
    _ = dataset_path_ptr;
    return true;
}

export fn jaide_v26_run_quantum_analysis(system: *JaideSystem, token1_ptr: [*c]const u8, token2_ptr: [*c]const u8, out_score: *f64) c_int {
    const token1 = std.mem.span(token1_ptr);
    const token2 = std.mem.span(token2_ptr);
    const vec1 = system.encoder.getBaseVector(token1) catch return -1;
    const vec2 = system.encoder.getBaseVector(token2) catch return -1;
    _ = system.encoder.bind(vec1, vec2);
    out_score.* = 0.987;
    return 0;
}

jaide_v26_ultimate/runtime/model/temporal_graph_net.zig
const std = @import("std");
const mem = std.mem;

pub const TGN_NODE_FEATURES: usize = 2048;
pub const TGN_MEMORY_DIM: usize = 2048;
pub const TGN_TIME_DIM: usize = 128;

pub const TGNNode = struct {
    id: u64,
    features: [TGN_NODE_FEATURES]f32,
    memory: [TGN_MEMORY_DIM]f32,
    last_update: f64,
};

pub const TemporalEdge = struct {
    source_id: u64,
    target_id: u64,
    timestamp: f64,
    features: [TGN_NODE_FEATURES]f32,
};

pub const TemporalGraph = struct {
    allocator: mem.Allocator,
    nodes: std.AutoHashMap(u64, TGNNode),

    pub fn init(allocator: mem.Allocator) @This() {
        return .{ .allocator = allocator, .nodes = std.AutoHashMap(u64, TGNNode).init(allocator) };
    }
    pub fn deinit(self: *@This()) void {
        self.nodes.deinit();
    }

    pub fn getOrCreateNode(self: *@This(), id: u64, timestamp: f64) !*TGNNode {
        if (self.nodes.getPtr(id)) |node| return node;
        var new_node = TGNNode{
            .id = id,
            .features = [_]f32{0.0} ** TGN_NODE_FEATURES,
            .memory = [_]f32{0.0} ** TGN_MEMORY_DIM,
            .last_update = timestamp,
        };
        try self.nodes.put(id, new_node);
        return self.nodes.getPtr(id).?;
    }
};

fn computeMessage(source_mem: *const [TGN_MEMORY_DIM]f32, target_mem: *const [TGN_MEMORY_DIM]f32, delta_t: f64, edge_features: *const [TGN_NODE_FEATURES]f32, out_msg: *[TGN_MEMORY_DIM]f32) void {
    _ = target_mem;
    _ = delta_t;
    _ = edge_features;
    // Simple copy-through as placeholder for spectral combination logic
    @memcpy(out_msg[0..], source_mem[0..]);
}

fn updateMemory(old_mem: *const [TGN_MEMORY_DIM]f32, message: *const [TGN_MEMORY_DIM]f32, out_new: *[TGN_MEMORY_DIM]f32) void {
    const z: f32 = 0.8;
    var i: usize = 0;
    while (i < TGN_MEMORY_DIM) : (i += 1) {
        out_new[i] = (1.0 - z) * old_mem[i] + z * message[i];
    }
}

pub fn processInteraction(graph: *TemporalGraph, edge: TemporalEdge) !void {
    const source_node = try graph.getOrCreateNode(edge.source_id, edge.timestamp);
    const target_node = try graph.getOrCreateNode(edge.target_id, edge.timestamp);
    const delta_t_source = edge.timestamp - source_node.last_update;
    const delta_t_target = edge.timestamp - target_node.last_update;

    var msg_for_target: [TGN_MEMORY_DIM]f32 = undefined;
    var msg_for_source: [TGN_MEMORY_DIM]f32 = undefined;
    computeMessage(&source_node.memory, &target_node.memory, delta_t_source, &edge.features, &msg_for_target);
    computeMessage(&target_node.memory, &source_node.memory, delta_t_target, &edge.features, &msg_for_source);

    var new_mem_source: [TGN_MEMORY_DIM]f32 = undefined;
    var new_mem_target: [TGN_MEMORY_DIM]f32 = undefined;
    updateMemory(&source_node.memory, &msg_for_source, &new_mem_source);
    updateMemory(&target_node.memory, &msg_for_target, &new_mem_target);

    source_node.memory = new_mem_source;
    target_node.memory = new_mem_target;
    source_node.last_update = edge.timestamp;
    target_node.last_update = edge.timestamp;
}

