pub const Context = struct {
    config: *c.futhark_context_config,
    context: *c.futhark_context,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) !*Context {
        const self = try allocator.create(Context);
        self.config = c.futhark_context_config_new();
        if (self.config == null) {
            allocator.destroy(self);
            return error.FutharkConfigFailed;
        }
        self.context = c.futhark_context_new(self.config);
        if (self.context == null) {
            c.futhark_context_config_free(self.config);
            allocator.destroy(self);
            return error.FutharkContextFailed;
        }
        self.allocator = allocator;
        return self;
    }

    pub fn deinit(self: *Context) void {
        _ = c.futhark_context_free(self.context);
        c.futhark_context_config_free(self.config);
        self.allocator.destroy(self);
    }
};

