const std = @import("std");
const mem = std.mem;

pub const SpectralMemoryLattice = struct {
    backing_allocator: mem.Allocator,
    lattice_memory: []u8,
    tgn_node_pool: std.heap.MemoryPool(TGNNode),
    hds_vector_buddy: mem.Allocator,

    pub const TGNNode = extern struct {
        features: f32,
        memory: f32,
    };

    pub fn init(backing_allocator: mem.Allocator, total_size_bytes: usize) !@This() {
        const lattice_memory = try backing_allocator.alloc(u8, total_size_bytes);
        var tgn_node_pool = std.heap.MemoryPool(TGNNode).init(backing_allocator);
        var buddy_fba = std.heap.FixedBufferAllocator.init(lattice_memory);
        return .{
            .backing_allocator = backing_allocator,
            .lattice_memory = lattice_memory,
            .tgn_node_pool = tgn_node_pool,
            .hds_vector_buddy = buddy_fba.allocator(),
        };
    }

    pub fn deinit(self: *@This()) void {
        self.tgn_node_pool.deinit();
        self.backing_allocator.free(self.lattice_memory);
    }

    pub fn allocator(self: *@This()) mem.Allocator {
        return .{ .ptr = self, .vtable = &vtable };
    }

    fn alloc(ctx: *anyopaque, len: usize, ptr_align: u8, ret_addr: usize) ?[*]u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        if (len == @sizeOf(TGNNode) and ptr_align <= @alignOf(TGNNode)) {
            return @ptrCast(self.tgn_node_pool.create() catch return null);
        }
        return self.hds_vector_buddy.rawAlloc(len, ptr_align, ret_addr);
    }

    fn resize(ctx: *anyopaque, buf: []u8, buf_align: u8, new_len: usize, ret_addr: usize) bool {
        _ = ctx; _ = buf; _ = buf_align; _ = new_len; _ = ret_addr;
        return false;
    }

    fn free(ctx: *anyopaque, buf: []u8, buf_align: u8, ret_addr: usize) void {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        const ptr_addr = @intFromPtr(buf.ptr);
        const lattice_start = @intFromPtr(self.lattice_memory.ptr);
        if (ptr_addr >= lattice_start and ptr_addr < lattice_start + self.lattice_memory.len) {
            self.hds_vector_buddy.rawFree(buf, buf_align, ret_addr);
        } else {
