const std = @import("std");
const mem = std.mem;
const rand = std.rand;

pub const HDS_DIM: usize = 10240;
pub const BipolarVec = [HDS_DIM]i8;

pub const HolographicEncoder = struct {
    allocator: mem.Allocator,
    item_memory: std.StringHashMap(BipolarVec),
    prng: rand.DefaultPrng,

    pub fn init(allocator: mem.Allocator) @This() {
        return .{
            .allocator = allocator,
            .item_memory = std.StringHashMap(BipolarVec).init(allocator),
            .prng = rand.DefaultPrng.init(0),
        };
    }

    pub fn deinit(self: *@This()) void {
        var it = self.item_memory.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
        }
        self.item_memory.deinit();
    }

    pub fn bind(a: BipolarVec, b: BipolarVec) BipolarVec {
        var result: BipolarVec = undefined;
        var i: usize = 0;
        while (i < HDS_DIM) : (i += 1) {
            result[i] = a[i] * b[i];
        }
        return result;
    }

    pub fn bundle(self: *@This(), vectors: []const BipolarVec) !BipolarVec {
        if (vectors.len == 0) return error.EmptyInput;
        var sum = [_]i32{0} ** HDS_DIM;
        var i: usize = 0;
        while (i < vectors.len) : (i += 1) {
            var j: usize = 0;
            while (j < HDS_DIM) : (j += 1) {
                sum[j] += vectors[i][j];
            }
        }
        var result: BipolarVec = undefined;
        var k: usize = 0;
        var rnd = self.prng.random();
        while (k < HDS_DIM) : (k += 1) {
            if (sum[k] > 0) result[k] = 1
            else if (sum[k] < 0) result[k] = -1
            else result[k] = if (rnd.boolean()) 1 else -1;
        }
        return result;
    }

    pub fn permute(v: BipolarVec, amount: u32) BipolarVec {
        _ = amount;
        var result: BipolarVec = undefined;
        var i: usize = 0;
        while (i < HDS_DIM) : (i += 1) {
            result[i] = v[i];
        }
        return result;
    }

    pub fn getBaseVector(self: *@This(), token: []const u8) !BipolarVec {
        if (self.item_memory.get(token)) |vec| return vec.*;
        var new_vec: BipolarVec = undefined;
        var rnd = self.prng.random();
        var i: usize = 0;
        while (i < HDS_DIM) : (i += 1) {
            new_vec[i] = if (rnd.boolean()) 1 else -1;
        }
        const key = try self.allocator.dupe(u8, token);
        try self.item_memory.put(key, new_vec);
        return new_vec;
    }

    pub fn encodeSequence(self: *@This(), tokens: [][]const u8) !BipolarVec {
        if (tokens.len == 0) return error.EmptyInput;
        var bundled = std.ArrayList(BipolarVec).init(self.allocator);
        defer bundled.deinit();

        if (tokens.len > 2) {
            var i: usize = 0;
            while (i + 2 < tokens.len) : (i += 1) {
                const v1 = try self.getBaseVector(tokens[i]);
                const v2 = try self.getBaseVector(tokens[i + 1]);
                const v3 = try self.getBaseVector(tokens[i + 2]);
                const trigram_vec = HolographicEncoder.bind(HolographicEncoder.bind(HolographicEncoder.permute(v1, 2), HolographicEncoder.permute(v2, 1)), v3);
                try bundled.append(trigram_vec);
            }
        } else {
            // Pairwise or single token case
            var i: usize = 0;
            while (i < tokens.len) : (i += 1) {
                const v = try self.getBaseVector(tokens[i]);
                try bundled.append(v);
            }
        }
        return self.bundle(bundled.items);
    }
};

