module spectral_processor {
  let cexp (theta: f32): (f32, f32) = (f32.cos theta, f32.sin theta)
  let cmul ((ar, ai): (f32, f32)) ((br, bi): (f32, f32)): (f32, f32) = (ar*br - ai*bi, ar*bi + ai*br)
  let cdiv ((ar, ai): (f32, f32)) ((br, bi): (f32, f32)): (f32, f32) =
    let d = br*br + bi*bi in if d == 0.0 then (0.0, 0.0) else ((ar*br + ai*bi)/d, (ai*br - ar*bi)/d)

  def permute_and_filter [n] (signal: [n]f32) (offset: i32) (permutation: f32): [n](f32, f32) =
    let indices = iota n
    let permuted_signal = map (\i -> let idx = (i * i32.f32 permutation + offset) % n in signal[idx]) indices
    in map ($$i, x) -> cmul (x, 0.0) (cexp (2.0 * f32.pi * f32.i32 (i*offset) / f32.i32 n))) (zip indices permuted_signal)

  def locate_frequency [b] (bin: [b](f32, f32)): f32 =
    let (r1, i1) = bin[b/2]
    let (r2, i2) = bin[b/2 - 1]
    let (ratio_r, ratio_i) = cdiv (r1, i1) (r2, i2)
    in f32.atan2 ratio_i ratio_r

  entry sparse_ft [n] (signal: [n]f32) (k: i32): ([k]i32, [k](f32, f32)) =
    loop (residual_signal, freqs, coeffs) = (signal, replicate k 0i32, replicate k (0.0f32, 0.0f32))
    for i < k do
      let offset = i + 1
      let permutation = 1.73205f32
      let filtered_signal = permute_and_filter residual_signal offset permutation
      let energies = map ($$r,i) -> r*r + i*i) filtered_signal
      let max_energy_idx = i32.argmax energies
      let freq_estimate_rad = locate_frequency filtered_signal[max_energy_idx-1:max_energy_idx+1]
      let freq_idx = i32.f32 (f32.round (f32.i32 n * freq_estimate_rad / (2.0 * f32.pi)))
      let indices_f32 = map f32.i32 (iota n)
      let twiddles = map (\j -> cexp (-2.0 * f32.pi * f32.i32 freq_idx * j / f32.i32 n)) indices_f32
      let signal_complex = map (\x -> (x, 0.0)) residual_signal
      let products = map2 cmul signal_complex twiddles
      let (sum_r, sum_i) = reduce ($$ar,ai) (br,bi) -> (ar+br, ai+bi)) (0.0, 0.0) products
      let coeff = (sum_r / f32.i32 n, sum_i / f32.i32 n)
      let component_to_subtract = map (\j -> cmul coeff (cexp (2.0 * f32.pi * f32.i32 freq_idx * j / f32.i32 n))) indices_f32
      let new_residual = map2 (\orig to_sub -> orig - (fst to_sub)) residual_signal component_to_subtract
      in (new_residual, update freqs [i] (freq_idx), update coeffs [i] (coeff))

