module mzi_controller #(
  parameter MATRIX_SIZE = 128,
  parameter DATA_WIDTH = 16,
  parameter ADDR_WIDTH = 10,
  parameter COMPUTATION_LATENCY = 10
)(
  input  wire                       clk,
  input  wire                       rst_n,
  input  wire [ADDR_WIDTH-1:0]      s_axi_awaddr,
  input  wire                       s_axi_awvalid,
  output reg                        s_axi_awready,
  input  wire [DATA_WIDTH-1:0]      s_axi_wdata,
  input  wire                       s_axi_wvalid,
  output reg                        s_axi_wready,
  output reg                        s_axi_bvalid,
  input  wire                       s_axi_bready,
  input  wire [ADDR_WIDTH-1:0]      s_axi_araddr,
  input  wire                       s_axi_arvalid,
  output reg                        s_axi_arready,
  output reg  [DATA_WIDTH-1:0]      s_axi_rdata,
  output reg                        s_axi_rvalid,
  input  wire                       s_axi_rready
);
  reg signed [DATA_WIDTH-1:0] weight_matrix [0:MATRIX_SIZE-1][0:MATRIX_SIZE-1];
  reg signed [DATA_WIDTH-1:0] input_vector  [0:MATRIX_SIZE-1];
  reg signed [DATA_WIDTH-1:0] output_vector [0:MATRIX_SIZE-1];
  reg                         start_computation, computation_done;
  reg [2:0]                   state;
  localparam S_IDLE=3'd0, S_LOAD_PHOTONICS=3'd1, S_COMPUTE_WAIT=3'd2, S_READ_PHOTONICS=3'd3, S_DONE=3'd4;
  reg [7:0]                   latency_counter;

  integer i, j;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= S_IDLE;
      latency_counter <= 0;
      computation_done <= 1'b0;
    end else begin
      case (state)
        S_IDLE: if (start_computation) state <= S_LOAD_PHOTONICS;
        S_LOAD_PHOTONICS: state <= S_COMPUTE_WAIT;
        S_COMPUTE_WAIT: begin
          if (latency_counter == COMPUTATION_LATENCY-1) state <= S_READ_PHOTONICS;
          else latency_counter <= latency_counter + 1;
        end
        S_READ_PHOTONICS: begin
          for (i = 0; i < MATRIX_SIZE; i = i + 1) begin
            integer acc;
            acc = 0;
            for (j = 0; j < MATRIX_SIZE; j = j + 1) begin
              acc = acc + (weight_matrix[i][j] * input_vector[j]);
            end
            output_vector[i] <= acc >>> 8;
          end
          state <= S_DONE;
        end
        S_DONE: begin
          computation_done <= 1'b1;
          state <= S_IDLE;
        end
      endcase
    end
  end
endmodule

