stadef size_t = int
absvtype buffer_v(n: int) = ptr
vtypedef buffer(n: int) = [l:addr] buffer_v(n) @ l

prfn in_bounds {n:int} {i:int} (i: size_t i, n: size_t n): bool (i < n) = "mac#%"

prfn region_in_bounds {n:int} {offset:int} {len:int}
  (pf: !in_bounds(offset + len - 1, n) | n: size_t n, offset: size_t offset, len: size_t len): void = "mac#%"

stadef msg_id_t = uint64
stadef payload_len_t = uint32
stadef msg_type_t = uint32

typedef header = @{ id=msg_id_t, len=payload_len_t, mtype=msg_type_t }

fun read_header {n:int | n >= 16} (pf: !in_bounds(15, n) | buf: buffer(n)): header =
  let
    val p_id = gptr_add<byte>(buf, 0)
    val p_len = gptr_add<byte>(buf, 8)
    val p_type = gptr_add<byte>(buf, 12)
  in
    @{ id = gptr_load<msg_id_t>(p_id), len = gptr_load<payload_len_t>(p_len), mtype = gptr_load<msg_type_t>(p_type) }
  end

vtypedef message(n: int) = @{ hdr=header, prfpf= (region_in_bounds(n, 0, hdr.len + 16) | ()) }

fun parse_message {n:int} (buf: buffer(n)): Option_vt (message(n)) =
  if n >= 16 then
    let
      prval pf_hdr = in_bounds(15, n)
      val hdr = read_header (pf_hdr | buf)
      val payload_len = gint2int(hdr.len)
      val required_len = payload_len + 16
    in
      if required_len <= n then
        let
          prval pf_payload = region_in_bounds {n} {0} {required_len} (in_bounds(required_len - 1, n) | n, 0, required_len)
          val msg = @{ hdr = hdr, prfpf = (pf_payload | ()) }
        in
          Some_vt(msg)
        end
      else None_vt()
    end
  else None_vt()

