include "../framework/vale_prelude.vad"
module ipc_parser

procedure parse_message_header(ghost buffer: seq<byte>, inout rdi: nat64, out rax: nat64, out rbx: nat32, out rcx: nat32)
    requires 0 <= rdi;
    requires |buffer| >= rdi + 16;
    modifies rax, rbx, rcx;
    ensures rax == u64(sub(buffer, rdi, 8));
    ensures rbx == u32(sub(buffer, rdi + 8, 4));
    ensures rcx == u32(sub(buffer, rdi + 12, 4));
{
    rax := Mem64[rdi];
    rbx := Mem32[rdi + 8];
    rcx := Mem32[rdi + 12];
}

procedure parse_and_get_payload_ptr(ghost buffer: seq<byte>, in rdi: nat64, in rsi: nat64, out rax: nat64, out rbx: nat32)
    requires 0 <= rdi;
    requires rdi <= rsi;
    requires |buffer| == rsi;
    modifies rax, rbx;
    ensures (rax == 0) ==> (!(rdi + 16 <= rsi && rdi + 16 + u64(u32(sub(buffer, rdi + 8, 4))) <= rsi));
    ensures (rax != 0) ==> (rbx == u32(sub(buffer, rdi + 8, 4)) && rax == rdi + 16 && rax + u64(rbx) <= rsi);
{
    var header_end: nat64;
    var carry: bool;
    carry, header_end := Add(rdi, 16);
    if carry || header_end > rsi {
        rax := 0;
        rbx := 0;
        return;
    }
    var msg_id: nat64;
    var msg_type: nat32;
    parse_message_header(buffer, rdi, msg_id, rbx, msg_type);
    var payload_len: nat64 := rbx;
    var payload_end: nat64;
    carry, payload_end := Add(header_end, payload_len);
    if carry || payload_end > rsi {
        rax := 0;
        return;
    }
    rax := header_end;
}

